(()=>{
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const scene=document.querySelector('.bossScene');scene.insertAdjacentHTML('beforeend','<div class="bossIcon"></div>');
const toolbar=document.createElement('div');toolbar.className='viewTools';toolbar.innerHTML='<span>✦ LINH ĐÀI · PHỐI CẢNH</span><div><button id="tiltView" aria-pressed="true">Nghiêng: bật</button><button id="wideView">⛶ Màn ngang</button></div>';document.querySelector('.arena').prepend(toolbar);
const deck=document.createElement('button');deck.id='drawPile';deck.title='Bộ rút · đổi các lá đã chọn';deck.innerHTML='<span>靈</span><small>BỘ RÚT</small>';deck.onclick=()=>selected.length?discardSelected():toast('Chọn lá rồi bấm bộ rút hoặc Đổi thẻ.');$('hand').before(deck);
let tilt=true;const arena=document.querySelector('.arena');
$('tiltView').onclick=()=>{tilt=!tilt;arena.style.setProperty('--rx','0deg');arena.style.setProperty('--ry','0deg');$('tiltView').textContent='Nghiêng: '+(tilt?'bật':'tắt');$('tiltView').setAttribute('aria-pressed',tilt)};
arena.addEventListener('pointermove',e=>{if(!tilt||reduced||e.pointerType==='touch')return;const r=arena.getBoundingClientRect();arena.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*3+'deg');arena.style.setProperty('--rx',-((e.clientY-r.top)/r.height-.5)*2+'deg')});arena.addEventListener('pointerleave',()=>{arena.style.setProperty('--rx','0deg');arena.style.setProperty('--ry','0deg')});
$('wideView').onclick=async()=>{if(window.AndroidHost){window.AndroidHost.toggleLandscape();return}try{if(document.fullscreenElement){await document.exitFullscreen();return}await document.documentElement.requestFullscreen();if(screen.orientation?.lock)await screen.orientation.lock('landscape')}catch{toast('Xoay ngang điện thoại để mở rộng bàn đấu.')}};
const oldRender=render;let prev=[];
render=function(){const fresh=s.hand.filter(id=>!prev.includes(id));oldRender();scene.dataset.boss=currentBoss().index;scene.querySelector('.bossIcon').innerHTML=bossEmblem(currentBoss());const cards=[...$('hand').children],n=cards.length;cards.forEach((el,i)=>{el.style.setProperty('--fan',(i-(n-1)/2)*2.1+'deg');el.style.setProperty('--lift',Math.pow(i-(n-1)/2,2)*1.1+'px');el.style.setProperty('--order',i);if(fresh.includes(+el.dataset.id)&&!reduced){const r=el.getBoundingClientRect(),d=deck.getBoundingClientRect();el.animate([{transform:`translate(${d.left-r.left}px,${d.top-r.top}px) rotate(-35deg) scale(.55)`,opacity:0},{opacity:1,offset:.35},{transform:`translateY(${Math.pow(i-(n-1)/2,2)*1.1}px) rotate(${(i-(n-1)/2)*2.1}deg)`,opacity:1}],{duration:650,delay:fresh.indexOf(+el.dataset.id)*65,easing:'cubic-bezier(.16,1,.3,1)'});}});prev=[...s.hand];
// Keep all equipment bays visible, including empty upgrade sockets.
for(const [id,cap,used,label]of[['jokers',5,s.j.length,'Cơ Duyên'],['tarots',3,s.tarots.length,'Luyện Đan']]){const root=$(id);if(!used)root.innerHTML='';for(let i=used;i<cap;i++)root.insertAdjacentHTML('beforeend',`<div class="upgradeSocket"><span>◇</span><small>${label} · ${i+1}</small></div>`)}
};
window.battleFX=(ids,damage,counter)=>{if(reduced)return;const boss=document.querySelector('.bossIcon');boss.animate([{filter:'brightness(1)'},{filter:'brightness(4)'},{filter:'brightness(1)'}],{duration:350});pulse('enemyFlash');for(let i=0;i<3;i++){const slash=document.createElement('i');slash.className='slash';slash.style.setProperty('--slash',(-35+i*30)+'deg');scene.append(slash);setTimeout(()=>slash.remove(),700)}
ids.forEach((id,i)=>{const c=card(id);if(!c)return;const node=document.createElement('div');node.className='flyingCard';node.innerHTML=weaponArt(c);document.body.append(node);const target=scene.getBoundingClientRect(),hand=$('hand').getBoundingClientRect();node.animate([{left:hand.left+hand.width*.5+'px',top:hand.top+'px',opacity:1,transform:'scale(.8) rotate(-15deg)'},{left:target.left+target.width*.5+'px',top:target.top+'px',opacity:0,transform:'scale(.3) rotate(25deg)'}],{duration:480,delay:i*50,fill:'forwards',easing:'ease-in'});setTimeout(()=>node.remove(),900)});
if(counter>0)setTimeout(()=>{pulse('playerFlash');document.querySelector('.mobileHUD').animate([{transform:'translateX(0)'},{transform:'translateX(-10px)',filter:'brightness(3)'},{transform:'translateX(9px)'},{transform:'translateX(-4px)'},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:450});const n=document.createElement('div');n.className='counterDamage';n.textContent='−'+counter+' HP';document.body.append(n);setTimeout(()=>n.remove(),800)},750);
};
function pulse(cls){const n=document.createElement('div');n.className='screenFX '+cls;document.body.append(n);setTimeout(()=>n.remove(),600)}
const oldUse=useTarot;useTarot=function(...args){const before=s.tarots.length;oldUse(...args);if(s.tarots.length<before&&!reduced){$('hand').animate([{filter:'brightness(1)'},{filter:'brightness(2) drop-shadow(0 0 14px #ffd68a)'},{filter:'brightness(1)'}],{duration:800})}};
render();
})();
